?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Custom Hosting Requests — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Custom Hosting</div><div class="portal-welcome"><div><span class="eyebrow mint">CUSTOM HOSTING</span><h1>My Custom Hosting Requests</h1><p>Track your custom hosting requirements and quoted prices.</p></div><a class="btn primary" href="custom-hosting.php">New Request</a></div><div class="admin-table"><?php if(!$rows):?><div class="empty">No custom hosting requests yet.</div><?php else:foreach($rows as $r):?><div class="admin-row"><div><strong>#<?=e($r['id'])?> · <?=e($r['quoted_product_name']??'Custom Hosting')?></strong><small><?=e($r['created_at'])?> · <?=e(ucwords(str_replace('_',' ',$r['status'])))?></small></div><span><?= $r['quoted_price']!==null ? money($r['quoted_price'],$r['quoted_currency']?:'BDT') : 'Quote pending' ?></span><?php if($r['order_number']):?><a class="btn secondary small" href="order-details.php?order=<?=urlencode($r['order_number'])?>">View Order</a><?php endif;?></div><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
